spec.expr:
((
  drift_metric_value{feature!="prediction"}

  or

  label_replace(
    drift_status{feature!="prediction"},
    "metric",
    "${1}_status",
    "metric",
    "(.+)"
  )

  or

  label_replace(
    drift_status_feature{feature!="prediction"},
    "metric",
    "Status",
    "feature",
    ".+"
  )

  or

  label_replace(
    group by (feature) (
      drift_metric_value{
        feature!="prediction",
        type="numeric"
      }
    ),
    "metric",
    "Type",
    "feature",
    ".+"
  )

  or

  label_replace(
    2 * group by (feature) (
      drift_metric_value{
        feature!="prediction",
        type="categorical"
      }
    ),
    "metric",
    "Type",
    "feature",
    ".+"
  )
)

and on(feature)

(
  drift_status_feature{feature!="prediction"}
  ${status_filter:raw}
)
)
or on()
label_replace(
  label_replace(
    vector(-1),
    "feature", "Collecting data", "", ""
  ),
  "metric", "Loading", "", ""
)
